function restSound(enabled){if(native){post('restSound',{enabled});return;}stopNoise();if(enabled&&ensureAudio()){const b=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=b.getChannelData(0);let value=0;for(let i=0;i<data.length;i++){value=(value+Math.random()*.03-.015)/1.02;data[i]=value;}noise=audioContext.createBufferSource();noise.buffer=b;noise.loop=true;const gain=audioContext.createGain();gain.gain.value=.14;noise.connect(gain);gain.connect(audioContext.destination);noise.start();nativeInfo.restSoundPlaying=true;}render();}
