 if(native)post('drowsyStart',{requestId:'drowsy-'+Date.now()});
 else{demoDrowsy={...IDLE_DROWSY,active:true,state:'locating',message:'가까운 쉼터를 찾고 있어요'};clearInterval(demoDrowsyTimer);let since=Date.now();demoDrowsyTimer=setInterval(()=>{const d=demoDrowsy;if(!d.active){clearInterval(demoDrowsyTimer);return;}const elapsed=(Date.now()-since)/1000;if(d.state==='locating'&&elapsed>1.2)demoDrowsy={...d,state:'guiding',restArea:{name:'죽암 졸음쉼터(서울)',road:'경부선',parking:22,toilet:true},distanceM:3200,waypoint:'requested',message:'경유지로 넣고 있어요'};else if(d.state==='guiding'){const moving=driving();demoDrowsy={...d,waypoint:elapsed>3.5?'confirmed':d.waypoint,distanceM:Math.max(120,d.distanceM-(moving?140:0)),state:d.distanceM<=300&&isParked()?'arrived':'guiding'};if(d.distanceM<=300&&!moving&&isParked())demoDrowsy.state='arrived';}drowsyTick();render();},1000);}
