function drowsyTalkStep(){const d=drowsy();if(!d.active||d.state!=='guiding'||!drowsyTalk||!sound||listening)return;speak(DROWSY_QUESTIONS[drowsyQuestion++%DROWSY_QUESTIONS.length]);drowsyAwaiting=true;drowsyListenAfterSpeech=true;if(native)setTimeout(()=>{if(drowsyListenAfterSpeech)drowsyListen();},9000);}
