const labels={temperature:'온도',fan:'풍량',brightness:'실내 조명',seatVentilation:'시트 통풍',hvacPower:'공조 전원',seatRecline:'시트 기울기',blind:'블라인드',voice:'음성 안내',restSound:'휴식 소리',window:'창문',seatPosition:'좌석 위치'};
function knownValue(value){return Number.isFinite(value)||typeof value==='boolean';}
function compactValue(key,value){if(!knownValue(value))return '값 미확인';if(key==='hvacPower')return value?'켜짐':'꺼짐';if(['seatRecline','blind'].includes(key))return value+' · 위치값';return valueLabel(key,value);}
