function valueLabel(key,value){if(value==null)return '값 선택';if(key==='temperature')return value+'°C';if(key==='brightness')return (typeof value==='boolean'?10:value)+' · 밝기값';if(key==='hvacPower')return value?'켜기':'끄기';if(['seatRecline','blind'].includes(key))return value+' · 차량 위치값';return value===0?'끄기':value+'단계';}
function formatRemaining(){const ms=native?state.alarm.remainingMs:demoAlarm?demoAlarm.end-performance.now():0,sec=Math.ceil(Math.max(0,ms)/1000);return Math.floor(sec/60).toString().padStart(2,'0')+':'+(sec%60).toString().padStart(2,'0');}
function durations(){return `<div class="duration" role="group" aria-label="휴식 시간">${C.NAPS.map(n=>`<button data-config="napMinutes" data-value="${n}" aria-pressed="${state.napMinutes===n}" ${!isParked()||activeAlarm()?'disabled':''}>${n}분</button>`).join('')}</div>`;}
