  el.querySelector('.step-detail').textContent=detail;el.querySelector('.step-detail').hidden=!detail;el.querySelector('.step-meter').dataset.kind=bar.kind;el.querySelector('.step-meter').hidden=bar.kind==='none'||!!alert;el.querySelector('.step-meter span').style.width=bar.value===null?'32%':Math.round(bar.value*100)+'%';el.setAttribute('aria-label',row.label+' · '+(SleepRoutine.states[row.state]||row.state)+(detail?' · '+detail:''));
