function updateGroups(list,rows,alert){
 let overview=list.querySelector('.routine-overview');if(!overview){overview=document.createElement('div');overview.className='routine-overview';overview.setAttribute('aria-label','함께 준비하는 차량 설정');list.prepend(overview);}
 for(const group of SleepRoutine.groups(rows)){
  let el=overview.querySelector(`[data-group="${group.id}"]`);if(!el){el=document.createElement('div');el.className='routine-group';el.dataset.group=group.id;el.innerHTML='<strong></strong><span class="group-status"></span><span class="group-detail"></span><div class="step-meter" aria-hidden="true"><span></span></div>';overview.append(el);}
  const row=group.active[0],bar=row?SleepRoutine.meter(row):{kind:'none',value:0};el.dataset.state=alert?'stopped':group.state;el.querySelector('strong').textContent=group.label;
  el.querySelector('.group-status').textContent=alert?'중단 확인':row?row.label+' · '+SleepRoutine.states[row.state]:group.failed?group.failed+'개 확인 필요':group.state==='confirmed'?group.confirmed+'개 확인':group.state==='queued'?'순서 대기':'현재 유지';
  const detail=row?SleepRoutine.freshPosition(row)?'현재 '+row.observed+' → 목표 '+(row.target??row.requested)+' · 위치값':knownValue(row.target??row.requested)?'목표 '+compactValue(row.key,row.target??row.requested)+' · 요청':'차량 응답 확인 중':group.rows.some(x=>x.state==='blocked')?'공조 전원 미확인 · 후속 설정 중단':group.rows.filter(x=>SleepRoutine.confirmed.has(x.state)&&knownValue(x.actual)).map(x=>x.label+' '+compactValue(x.key,x.actual)).join(' · ');
  el.querySelector('.group-detail').textContent=detail;el.querySelector('.group-detail').hidden=!detail;el.querySelector('.step-meter').hidden=bar.kind==='none'||!!alert;el.querySelector('.step-meter').dataset.kind=bar.kind;el.querySelector('.step-meter span').style.width=bar.value===null?'32%':Math.round(bar.value*100)+'%';
 }
}
function action(a){if(!a)return;if(a.startsWith('sound-')){const kind=a.slice(6);if(native)post('restSoundKind',{kind});else{demoSoundKind=kind;render();}return;}if(a==='drowsy-start'){startDrowsy();return;}if(a==='drowsy-stop'){stopDrowsy();return;}if(a==='drowsy-rest'){markTrip(true);stopDrowsy();action('rest-mode');return;}if(a==='drowsy-start')markTrip(false);if(a==='drowsy-air'){const on=drowsy().comfort?.fan?.state==='applied';drowsyComfort(on?{fan:1,seatVentilation:0}:{fan:3,seatVentilation:2});return;}if(a==='drowsy-window'){const on=drowsy().comfort?.window?.state==='applied';drowsyComfort({window:!on});return;}if(a==='drowsy-talk'){drowsyTalk=!drowsyTalk;if(!drowsyTalk)stopSpeech();render();return;}if(a==='rest-mode'){if(!state.sleepProfileInitialized&&isParked()&&!busy()&&!activeAlarm()&&!nativeInfo.pendingRestore)dispatch({type:'sleep-preset'});dispatch({type:a});return;}if(a==='reload-sleep-preset'){dispatch({type:'sleep-preset'});return;}if(a==='capture-pose'){if(!isParked()||busy()||activeAlarm()||nativeInfo.pendingRestore)return;poseCaptureRequestedAt=Date.now();if(native)post('captureRestPose');else{nativeInfo.restPose={status:'ready',capturedAt:Date.now(),message:'브라우저 예시 자세를 저장했어요 · 실제 차량과 무관',seatRecline:{value:55,areaId:nativeInfo.controlCapabilities.seatRecline.areaId},blind:{value:80,areaId:nativeInfo.controlCapabilities.blind.areaId}};poseCaptureRequestedAt=0;dispatch({type:'sleep-preset'});}render();return;}if(a==='navigate'){if(native)post('navigate');else{dialogue='브라우저에서는 차량 내비를 열 수 없어요.';render();}return;}if(a==='open-demo'){if(isParked()&&!busy()&&!activeAlarm()&&!nativeInfo.pendingRestore){if(native)post('openDemo');else location.href='demo/index.html';}return;}if(a==='home'){if(isParked()&&!activeAlarm()&&!busy()){screen='home';dispatch({type:'reset'});}return;}if(a==='planning'){if(isParked()&&!busy()){screen='planning';render();}return;}if(a==='journal'){if(isParked()&&!activeAlarm()&&!busy()){screen='journal';render();}return;}if(a==='journal-close'){screen='home';render();return;}if(a==='close-settings'){dispatch({type:'close-settings'});return;}if(a==='edit-settings'){if(!state.sleepProfileInitialized&&isParked()&&!busy()&&!activeAlarm()&&!nativeInfo.pendingRestore)dispatch({type:'sleep-preset'});if(state.phase==='prepare')dispatch({type:'consent-environment',value:false});dispatch({type:a});return;}if(a.startsWith('adjust:')){const [,key,d]=a.split(':'),cap=nativeInfo.controlCapabilities?.[key];if(!cap||!isParked())return;const value=state.preset[key],next=value==null?cap.min:Math.round((value+Number(d)*cap.step)*1000)/1000;if(next<cap.min||next>cap.max)return;dispatch({type:'configure',preset:{[key]:next,...(key==='blind'?{blindArea:cap.areaId||''}:{})}});return;}if(a==='timer-only'){if(state.phase!=='prepare'||!isParked()||!state.confirmedPlace||busy())return;dispatch({type:'consent-environment',value:false});a='rest';}if(a==='rest'){ensureAudio();dispatch({type:'rest',requestId:'rest-'+Date.now()+'-'+Math.random().toString(36).slice(2,8)});return;}if(a==='listen'){if(native){if(!nativeInfo.stt)return;listening=true;post('listen');dialogue='듣고 있어요. 깨비 휴식 또는 깨비 졸음모드라고 말해 주세요.';}else{dialogue='시연 명령 “깨비 졸음모드”를 처리했어요.';dispatch({type:'drowsy-mode'});}render();return;}if(a==='checkin'){speak('졸리면 안전하게 진입할 수 있는 가장 가까운 휴식 장소를 확인해 주세요.');return;}if(a==='sync-alarm'){native?post('ready'):demoSignal();return;}if(a==='alarm-permission'){post('requestAlarmPermission');return;}if(a==='toggle-rest-sound'){if(isParked())restSound(!nativeInfo.restSoundPlaying);return;}if(['restore-controls','recovered'].includes(a)&&busy())return;dispatch({type:a});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.option){selectedOption=b.dataset.option;render();return;}if(b.dataset.dim){dispatch({type:'configure',preset:{dim:b.dataset.dim==='true'}});return;}if(b.dataset.power){dispatch({type:'configure',preset:{hvacPower:b.dataset.power==='true'}});return;}if(b.dataset.action)action(b.dataset.action);if(b.dataset.config)dispatch({type:'configure',[b.dataset.config]:b.dataset.config==='sleep'?b.dataset.value:Number(b.dataset.value)});});
