document.addEventListener('change',e=>{if(e.target.id==='option-select'){selectedOption=e.target.value;render();return;}const el=e.target,key=el.dataset.adjustRange;if(!key||el.disabled||!isParked()||busy()||activeAlarm())return;const m=optionMeta(key);if(key!=='window'&&m.supported)dispatch({type:'configure',preset:{[key]:Number(el.value),...(key==='blind'?{blindArea:m.cap.areaId||''}:{})}});});
document.addEventListener('change',e=>{const el=e.target;if(el.disabled||!el.dataset.check)return;if(el.dataset.check==='all'){for(const type of ['confirm-place','consent-environment','consent-cabin','consent-motion'])dispatch({type,value:el.checked});return;}const key=el.dataset.check,type={place:'confirm-place',environment:'consent-environment',cabin:'consent-cabin',motion:'consent-motion',autoRestore:'auto-restore'}[key];if(type)dispatch({type,value:el.checked});else dispatch({type:'configure',preset:{[key]:el.checked}});});
$('#sound').onclick=()=>{sound=!sound;if(sound)speak('필요한 때만 짧게 안내할게요.');else{stopSpeech();dispatch({type:'quiet'});}render();};
$('#simulator').onclick=e=>{const a=e.target.closest('button')?.dataset.sim;if(!a||native)return;if(a==='park'){demoGear='P';demoSpeed=0;demoLost=false;}if(a==='drive'){demoGear='D';demoSpeed=80;demoLost=false;}if(a==='lost')demoLost=true;if(a==='wake'&&demoAlarm){demoAlarm.state='ringing';demoAlarm.end=performance.now();}if(a==='reset'){demoJobs.forEach(clearTimeout);demoJobs=[];demoAlarm=null;nativeInfo={};state=C.initial(Date.now(),'demo');demoGear='P';demoSpeed=0;demoLost=false;screen='home';dialogue='';}demoSignal();};
setInterval(()=>{if(!native){if(demoAlarm?.state==='scheduled'&&performance.now()>=demoAlarm.end)demoAlarm.state='ringing';demoSignal();}else{dispatch({type:'tick'});$('#countdown').textContent=formatRemaining();}},1000);
